class Solution {
public:
    string removeDuplicates(string s, int k) {
        vector<pair<char, int>> st;
        for (char ch : s) {
            if (!st.empty() && st.back().first == ch) {
                st.back().second++;
                if (st.back().second == k) {
                    st.pop_back();
                }
            } else {
                st.push_back({ch, 1});
            }
        }
        string res;
        for (auto& p : st) {
            res.append(p.second, p.first);
        }
        return res;
    }
};

class Solution {
    public String removeDuplicates(String s, int k) {
        StringBuilder sb = new StringBuilder();
        int[] counts = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            sb.append(ch);
            int len = sb.length();
            if (len > 1 && sb.charAt(len - 2) == ch) {
                counts[len - 1] = counts[len - 2] + 1;
            } else {
                counts[len - 1] = 1;
            }
            if (counts[len - 1] == k) {
                sb.delete(len - k, len);
            }
        }
        return sb.toString();
    }
}

var removeDuplicates = function(s, k) {
    const st = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (st.length > 0 && st[st.length - 1][0] === ch) {
            st[st.length - 1][1]++;
            if (st[st.length - 1][1] === k) {
                st.pop();
            }
        } else {
            st.push([ch, 1]);
        }
    }
    return st.map(([ch, count]) => ch.repeat(count)).join('');
};
